layer.css:
[data-ryt="pitch"] { color: rgb(122, 122, 122); background-color: rgba(255, 255, 255, 0.05); border-left: 4px solid var(--ryt-accent); border-radius: 8px; box-shadow: rgba(0, 0, 0, 0.05) 0px 2px 8px 0px; font-family: var(--ryt-font-heading); font-size: 20px; font-weight: 300; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(122, 122, 122); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 20px; padding-right: 30px; padding-bottom: 20px; padding-left: 30px; transition: all; border-top: none; border-right: none; border-bottom: none }
article[data-ryt="rec-card"] { border-bottom: 1px solid rgba(0, 0, 0, 0); border-radius: 0px; transition: 0.2s; border-top: none; border-right: none; border-left: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-bottom: 1px solid rgba(0, 0, 0, 0); border-radius: 0px; font-weight: 300; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.2s, text-decoration 0.2s; border-top: none; border-right: none; border-left: none }
[data-ryt="hero"] h1 { color: rgb(48, 48, 48); font-family: var(--ryt-font-heading); font-size: 44px; font-weight: 700; font-style: normal; line-height: 1.3; letter-spacing: -0.88px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(48, 48, 48); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="section"] > h2 { color: rgb(48, 48, 48); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 300; font-style: normal; line-height: 1.25; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(48, 48, 48); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-border); border-bottom: 1px solid rgba(0, 0, 0, 0); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 300; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-border); text-decoration-thickness: auto; text-underline-offset: auto; transition: 0.2s; border-top: none; border-right: none; border-left: none }
[data-ryt="button"] { color: rgb(0, 0, 0); background-color: var(--ryt-text); border-radius: 50%; font-family: Arial; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(0, 0, 0); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: rgb(48, 48, 48); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 20px; font-weight: 500; font-style: normal; line-height: 1.5; letter-spacing: -0.4px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(48, 48, 48); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.2s }
[data-ryt="rec-card"] [data-ryt="title"]:hover { color: #268bd2 }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
article[data-ryt="rec-card"]:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
